from ta_emss.utilities.trs.commands.emssim import EmssimCommand


def convert_to_string_in_lowercase(value):
    return str(value).lower()


def change_keys_to_lowercase(dictionary):
    return {convert_to_string_in_lowercase(key): value for key, value in dictionary.items()}


def convert_structure_to_lowercase(structure, lower_values=True):
    if isinstance(structure, dict):
        converted_structure = {convert_to_string_in_lowercase(key): convert_structure_to_lowercase(value, lower_values) for key, value in structure.items()}
    elif isinstance(structure, list):
        converted_structure = [convert_structure_to_lowercase(element) for element in structure]
    elif lower_values:
        converted_structure = convert_to_string_in_lowercase(structure)
    else:
        converted_structure = str(structure)
    return converted_structure


class Disp(EmssimCommand):
    def __init__(self, method="disp", timeout=60, rpc_connection_name='localRPC', lower_values=True):
        super(Disp, self).__init__(method, timeout, rpc_connection_name)
        self.params = None
        self.lower_values = lower_values

    def on_new_data(self, **data):
        data = super(Disp, self).on_new_data(**data)
        if "msg" in data:
            if "Completed DISP with get attributes" in data["msg"]:
                if 'attributes' not in self._ret:
                    self._ret['attributes'] = {}
                for object, attr in data['attributes'].items():
                    self._ret['attributes'][object] = convert_structure_to_lowercase(attr, self.lower_values)
        elif ("status" in data):
            self._ret["status"] = data["status"]
